package net.civeira.phylax.features.access.usermfaenrollment.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.crypto.KeyRingSecretStorage;

class PendingSeedVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property pending seed of user mfa enrollment ")
  void test_pending_seed_v_o_builder() {
    KeyRingSecretStorage service = Mockito.mock(KeyRingSecretStorage.class);
    Mockito.when(service.seal("small", "access.user_mfa_enrollment.pending_seed#owner"))
        .thenReturn("sealed:k0:example");
    Assertions.assertEquals("sealed:k0:example",
        PendingSeedVO.fromPlain("small").getPendingSeedStored(service, "owner").orElse(null));
    Assertions.assertEquals("****", PendingSeedVO.fromPlain("small").toString());
  }
}
